const questions=[...researchQuestions,
{id:'workweek',title:'월급이 그대로라면, 주 4일제에 찬성할까?',category:'일과 생활',a:'찬성',b:'반대',condition:'기존 월급 유지 · 주당 근무일 5일 → 4일',count:2841,value:72,range:[66,78],ages:[84,81,75,64,56],genders:[70,74],votes:[802,198],reasonA:'충분히 쉬어야 일할 때 더 집중할 수 있어요.',reasonB:'같은 업무를 4일 안에 끝내려면 하루가 너무 길어질 것 같아요.',color:'#edf1e8',ink:'#638052',label:'일하는 방식도\n선택의 시대',icons:['bag','coffee'],date:6},
{id:'wedding',title:'축의금 5만 원, 식사하고 와도 괜찮을까?',category:'관계와 일상',a:'괜찮다',b:'어렵다',condition:'일반 예식장 · 지인의 결혼식에 혼자 참석',count:1926,value:54,range:[45,63],ages:[68,61,52,46,43],genders:[56,52],votes:[550,450],reasonA:'축하하는 마음이 금액보다 중요하다고 생각해요.',reasonB:'요즘 식대까지 생각하면 조금 더 하는 게 좋겠어요.',color:'#f5ede7',ink:'#ab7756',label:'마음의 크기와\n봉투의 두께',icons:['heart','money'],date:5},
{id:'ai',title:'AI가 내 과제를 채점한다면, 받아들일 수 있을까?',category:'기술과 미래',a:'받아들인다',b:'어렵다',condition:'교사의 최종 검토와 이의 제기 절차 보장',count:1543,value:61,range:[51,71],ages:[76,69,61,51,42],genders:[63,59],votes:[660,340],reasonA:'일관된 기준으로 빠르게 피드백받을 수 있을 것 같아요.',reasonB:'정해진 답 밖의 창의적인 생각을 이해할 수 있을까요?',color:'#eaf0f7',ink:'#67819e',label:'새로운 기술,\n우리의 선택은?',icons:['cpu','book'],date:7},
{id:'remote',title:'월급 10% 인상 vs 주 4일제, 무엇을 선택할까?',category:'일과 생활',a:'월급 10% 인상',b:'주 4일제',condition:'주 4일제 선택 시 현재 월급 유지 · 업무량 동일',count:1268,value:48,range:[40,56],ages:[40,43,49,55,57],genders:[50,46],votes:[420,580],reasonA:'매달 고정 지출이 있어서 소득이 늘어나는 게 우선이에요.',reasonB:'하루의 여유는 돈으로 바꾸기 어려운 가치예요.',color:'#edf1e8',ink:'#638052',label:'더 많은 월급?\n더 많은 내 시간?',icons:['money','coffee'],date:3},
{id:'concert',title:'콘서트 VIP석 경매, 공정한 방식일까?',category:'문화와 취향',a:'공정하다',b:'불공정하다',condition:'일반석 정가 유지 · VIP석에만 공식 경매 적용',count:943,value:37,range:[26,48],ages:[28,32,39,43,49],genders:[40,34],votes:[280,720],reasonA:'암표 대신 공식 경로로 수요에 맞는 가격을 정할 수 있어요.',reasonB:'팬심보다 경제력이 기회를 결정하게 될 것 같아요.',color:'#f2ecf5',ink:'#94729f',label:'같은 무대,\n다른 기회의 가격',icons:['heart','money'],date:2},
{id:'cashless',title:'현금 없는 매장, 이제는 괜찮을까?',category:'관계와 일상',a:'괜찮다',b:'어렵다',condition:'카드·모바일 결제만 가능 · 현금 결제 불가',count:712,value:58,range:[48,68],ages:[82,75,61,43,29],genders:[60,56],votes:[710,290],reasonA:'대부분 카드나 휴대전화로 결제해서 더 편리해요.',reasonB:'디지털 기기가 익숙하지 않은 사람도 이용할 수 있어야 해요.',color:'#f4f0e2',ink:'#9b8950',label:'빠르고 편리하게,\n모두에게 같을까?',icons:['money','cpu'],date:1}];
const state={filter:'전체',sort:'popular',search:'',saved:new Set(),records:{},votes:{},drafts:[],group:'age',researchConditions:{}};
let storageAvailable=true;try{const s=JSON.parse(localStorage.getItem('minsim-demo-v1')||'{}');state.saved=new Set(Array.isArray(s.saved)?s.saved:[]);state.records=s.records&&typeof s.records==='object'?s.records:{};state.votes=s.votes&&typeof s.votes==='object'?s.votes:{};state.drafts=Array.isArray(s.drafts)?s.drafts:[]}catch{storageAvailable=false}
const persist=()=>{try{localStorage.setItem('minsim-demo-v1',JSON.stringify({...state,saved:[...state.saved]}))}catch{storageAvailable=false;toast('이 브라우저에서는 기록을 저장할 수 없어요. 현재 화면에서만 유지됩니다.')}};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('ko-KR');
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3000)}
function shell(content,active='home',label='민심 둘러보기'){document.querySelector('#app').innerHTML=`<header class="site-header"><div class="header-inner">${brand()}<nav class="nav" aria-label="주 메뉴">${[['compass','/','둘러보기','home'],['target','/predict/workweek','민심 맞히기','play'],['chart','/records','내 기록','records'],['bookmark','/saved','저장','saved']].map(([i,path,t,id])=>`<a href="#${path}" aria-label="${t}" class="${active===id||active==='feed'&&id==='home'?'active':''}" ${active===id||active==='feed'&&id==='home'?'aria-current="page"':''}>${icon(i)}<span>${t}</span></a>`).join('')}</nav><form id="search-form" class="header-search">${icon('search')}<input type="search" name="search" aria-label="질문 검색" placeholder="등록된 질문 검색" value="${active==='feed'?esc(state.search):''}"><button type="submit" aria-label="검색">${icon('arrow')}</button></form></div></header><main id="main" class="content ${active==='play'?'game-content':''}" tabindex="-1">${content}<footer class="footer"><span>실행 결과·예시 구분 제공 · 실제 여론조사 아님</span><button data-action="about">서비스·데이터 안내 ${icon('info')}</button><span>© 민심테스트</span></footer></main>`;}
function card(q){if(q.research)return researchCard(q,state.saved.has(q.id));return `<article class="question-card"><div class="market-card-heading"><span class="topic-icon topic-${q.id}">${icon(q.icons[0])}</span><span class="category">${q.category}</span><button class="bookmark ${state.saved.has(q.id)?'saved':''}" data-action="save" data-id="${q.id}" aria-label="${esc(q.title)} 저장" aria-pressed="${state.saved.has(q.id)}">${icon('bookmark')}</button></div><h3><a href="#/predict/${q.id}">${q.title}</a></h3><div class="market-options" aria-label="질문의 두 선택지"><div><span>${q.a}</span><b>A</b></div><div><span>${q.b}</span><b>B</b></div></div><div class="question-footer"><span>${fmt(q.count)}명 참여 · 예시</span><a href="#/predict/${q.id}" class="join">${state.records[q.id]?'내 결과 보기':'예측하기'} ${icon('arrow')}</a></div></article>`}
function feedCards(){let qs=questions.filter(q=>(state.filter==='전체'||q.category===state.filter)&&(!state.search||q.title.includes(state.search)));if(state.sort==='latest')qs.sort((a,b)=>b.date-a.date);if(state.sort==='balanced')qs.sort((a,b)=>Math.abs(a.value-50)-Math.abs(b.value-50));if(state.sort==='popular')qs.sort((a,b)=>b.count-a.count);return qs.map(card).join('')||'<div class="empty"><h2>아직 이런 질문은 없네요</h2><p>다른 검색어로 찾아보거나 직접 질문을 만들어 보세요.</p><button class="primary" data-action="create">질문 만들기</button></div>'}
function filters(){return `<div class="feed-controls"><div class="filters" aria-label="질문 카테고리">${['전체','일과 생활','관계와 일상','기술과 미래','문화와 취향'].map(t=>`<button class="filter ${state.filter===t?'active':''}" data-action="filter" data-value="${t}" aria-pressed="${state.filter===t}">${t}</button>`).join('')}</div><select class="sort" aria-label="질문 정렬"><option value="popular" ${state.sort==='popular'?'selected':''}>인기순</option><option value="latest" ${state.sort==='latest'?'selected':''}>최신순</option><option value="balanced" ${state.sort==='balanced'?'selected':''}>반반인 질문</option></select></div>`}
function home(){state.search='';shell(`<section class="question-composer" aria-labelledby="composer-heading"><h1 id="composer-heading">이거, 나만 궁금해?</h1><form id="quick-question" class="composer-box"><label for="quick-question-input" class="visually-hidden">대한민국에 물어볼 질문</label><textarea id="quick-question-input" name="question" rows="2" minlength="8" maxlength="180" required aria-describedby="composer-help" placeholder="예: 월급이 조금 줄어도 주 4일제를 선택할까?"></textarea><div class="composer-toolbar"><span>궁금한 건 뭐든, 대한민국에 물어보세요</span><button type="submit" class="primary composer-send">질문하기 ${icon('arrow')}</button></div></form><p id="composer-help" class="composer-help">현재는 체험판이에요. 질문을 다듬어 나만의 초안으로 저장할 수 있어요.</p></section><div class="home-columns"><div class="home-primary"><section class="topic-section research-home"><div class="section-heading"><h2>직접 돌려본 민심</h2><span class="micro">1,200명 기반 시뮬레이션</span></div><div class="question-grid">${researchQuestions.map(card).join('')}</div></section><div class="home-heading"><h2>지금 궁금한 민심</h2><span class="demo-pill">예시 데이터 체험판</span></div><div class="market-dashboard"><section class="featured-market"><div class="featured-copy"><div class="featured-category"><span class="topic-icon">${icon('bag')}</span><span>오늘의 질문 · 일과 생활</span></div><h2>월급이 그대로라면,<br>주 4일제에 찬성할까?</h2><p class="featured-condition">기존 월급 유지 · 주당 근무일 5일 → 4일</p><div class="featured-footnote">대한민국 만 18세 이상을 가정한 질문</div></div><div class="featured-predict"><div class="featured-prompt">대한민국의 선택을 예상해 보세요</div><div class="market-options"><div><span>찬성</span><b>A</b></div><div><span>반대</span><b>B</b></div></div><a class="primary full" href="#/predict/workweek">${state.records.workweek?'내 결과 보기':'민심 예측하기'} ${icon('arrow')}</a><span class="micro">비율은 예측을 마치면 공개돼요</span></div></section></div>${[...new Set(questions.map(q=>q.category))].map((category,i)=>{const items=questions.filter(q=>!q.research&&q.category===category);return `<section class="topic-section" aria-labelledby="topic-heading-${i}"><div class="section-heading"><h2 id="topic-heading-${i}">${category}</h2><span class="micro">${items.length}개 질문</span></div><div class="question-grid">${items.map(card).join('')}</div></section>`}).join('')}</div><aside class="home-sidebar" aria-label="추천 질문 목록">${[{title:'많이 보는 질문',note:'참여 수 기준 · 예시',items:questions.filter(q=>!q.research).sort((a,b)=>b.count-a.count)},{title:'새로 나온 질문',note:'최근 추가된 질문',items:[...questions].sort((a,b)=>b.date-a.date)}].map(list=>`<section class="trending-panel"><div class="sidebar-heading"><h2>${list.title}</h2><span class="micro">${list.note}</span></div>${list.items.slice(0,3).map((item,i)=>`<a class="trending-row" href="#/predict/${item.id}"><span class="trend-index">${i+1}</span><div><strong>${item.title}</strong><span>${item.category}</span></div>${icon('chevron')}</a>`).join('')}</section>`).join('')}</aside></div>`)}
function explore(saved=false){shell(`<div class="page-heading"><div><h1>${saved?'저장한 질문':state.search?'검색 결과':'질문 둘러보기'}</h1>${state.search&&!saved?`<p>‘${esc(state.search)}’ 관련 질문</p>`:''}</div><span class="demo-pill">실행 결과·예시 구분 제공</span></div>${saved?'':filters()}<div class="question-grid" id="feed-grid">${saved?(questions.filter(q=>state.saved.has(q.id)).map(card).join('')||'<div class="empty">'+icon('bookmark')+'<h2>관심 있는 질문을 저장해 보세요</h2><p>질문 카드의 책갈피를 누르면 여기에 모여요.</p><a class="primary" href="#/feed">질문 둘러보기</a></div>'):feedCards()}</div>`,saved?'saved':'feed',saved?'저장한 질문':'질문 둘러보기')}
function prediction(q){if(q.research){result(q);return}const previous=state.records[q.id];if(previous){result(q);return}shell(`<a class="text-button back-link" href="#/feed">${icon('back')} 다른 질문 고르기</a><div class="flow-steps"><span class="current">01 <b>예측하기</b></span><i></i><span>02 <b>결과 공개</b></span><i></i><span>03 <b>내 생각 투표</b></span></div><div class="play-layout"><section class="panel prediction-panel"><div class="pill-row"><span class="tag">${q.category}</span><span class="demo-pill">예시 데이터 체험</span></div><h1>${q.title}</h1><p class="conditions">대한민국 만 18세 이상 · ${q.condition}</p><div class="predict-prompt">대한민국에서 <strong>‘${q.a}’</strong>를 고를 비율은?</div><form id="prediction-form" data-id="${q.id}"><div class="prediction-number"><input id="prediction-number" type="number" name="prediction" aria-label="${q.a} 예상 비율" value="50" min="0" max="100" step="1" required><span>%</span></div><div class="slider-wrap"><input id="prediction-range" type="range" min="0" max="100" value="50" aria-label="${q.a} 예상 비율 조절" aria-valuetext="50퍼센트" style="--fill:50%"><div class="slider-labels"><span>0%</span><span>50% · 절반</span><span>100%</span></div></div><div class="prediction-options"><span>${q.a}<b id="option-a">50%</b></span><span>${q.b}<b id="option-b">50%</b></span></div><button type="submit" class="primary full">예측하고 결과 보기 ${icon('arrow')}</button><p class="micro centered">처음 예측이 기록돼요. 결과 공개 후에는 바꿀 수 없어요.</p></form></section><details class="game-help"><summary>플레이 안내 · 점수는 어떻게 계산하나요?</summary><p>내 의견이 아닌 대한민국의 선택 비율을 예상해 주세요. 점수는 100 − 예시 결과와의 차이(%p) × 2로 계산하며, 0–100점 사이예요. 모델 정확도를 뜻하지 않아요.</p></details><p class="micro centered" style="margin-top:20px">화면 시연용 예시 · 실제 시뮬레이션 미실행</p></div>`,'play','민심 맞히기')}
function fixtureNote(){return '<figcaption class="chart-note">화면 시연용 예시 · 실제 시뮬레이션 미실행 · 신뢰도 미평가</figcaption>'}
function groups(q){const age=state.group==='age',labels=age?['18–29세','30대','40대','50대','60세 이상']:['남성','여성'],values=age?q.ages:q.genders;return `<figure class="group-chart"><div class="group-legend"><span>‘${q.a}’ 선택 비율</span><span>0% — 100%</span></div>${labels.map((l,i)=>`<div class="group-row"><span>${l}</span><div class="group-track"><div style="width:${values[i]}%"></div></div><b>${values[i]}%</b></div>`).join('')}${fixtureNote()}</figure>`}
function scoreFor(q,r){return Math.max(0,100-Math.abs(q.value-r.prediction)*2)}
function visitor(q){const vote=state.votes[q.id];const a=q.votes[0]+(vote==='a'?1:0),b=q.votes[1]+(vote==='b'?1:0),p=Math.round(a/(a+b)*100);return `<div class="section-heading compact"><div><div class="eyebrow">YOUR VOICE MATTERS</div><h2>그럼, 당신의 생각은?</h2></div><span class="demo-pill">방문자 투표 체험</span></div><p class="body-muted">이번에는 예상 말고, 내 선택!</p><div class="vote-buttons"><button class="vote-button ${vote==='a'?'selected':''}" data-action="vote" data-id="${q.id}" data-value="a" aria-pressed="${vote==='a'}">${vote==='a'?icon('check'):''}${q.a}</button><button class="vote-button ${vote==='b'?'selected':''}" data-action="vote" data-id="${q.id}" data-value="b" aria-pressed="${vote==='b'}">${vote==='b'?icon('check'):''}${q.b}</button></div>${vote?`<figure class="visitor-chart"><div class="bar-labels"><span>${q.a} <b>${p}%</b></span><span>${q.b} <b>${100-p}%</b></span></div><div class="result-bar visitor"><span style="width:${p}%"></span><span style="width:${100-p}%"></span></div><figcaption class="chart-note">방문자 분포 예시 ${fmt(q.votes[0]+q.votes[1])}표 + 이 브라우저의 체험 투표 1표<br>실제 방문자 통계가 아니며 전국민을 대표하지 않습니다.</figcaption></figure><p class="vote-confirm">${icon('check')} ‘${vote==='a'?q.a:q.b}’에 투표했어요. 다른 선택지를 누르면 변경돼요.</p>`:'<p class="micro">투표는 이 브라우저에만 저장되며, 실제 서비스에 전송되지 않아요.</p>'}`}
function result(q){if(q.research){const condition=state.researchConditions[q.id]||q.defaultCondition;shell(researchContent(q,condition,state.votes[q.id+':'+condition],state.saved.has(q.id)),'play');return}const r=state.records[q.id];if(!r){prediction(q);return}const error=Math.abs(q.value-r.prediction),score=scoreFor(q,r),next=questions[(questions.indexOf(q)+1)%questions.length];shell(`<a href="#/feed" class="text-button back-link">${icon('back')} 다른 질문 고르기</a><div class="result-heading"><div class="pill-row"><span class="tag">결과 공개</span><span class="demo-pill">합성 인구 결과 · 예시</span></div><h1>${q.title}</h1><p>대한민국 만 18세 이상 · ${q.condition}</p></div><div class="result-layout"><div class="result-main"><section class="panel"><div class="section-heading compact"><h2>합성 인구의 예상 응답</h2><button class="text-button" data-action="evidence">신뢰도 미평가 ${icon('info')}</button></div><figure class="overall-chart"><div class="result-numbers"><div><span>${q.a}</span><strong>${q.value}<small>%</small></strong></div><span class="vs-small">VS</span><div><span>${q.b}</span><strong>${100-q.value}<small>%</small></strong></div></div><div class="result-bar"><span style="width:${q.value}%"></span><span style="width:${100-q.value}%"></span></div><div class="range-note"><span>${q.a} 범위 예시 <b>${q.range[0]}–${q.range[1]}%</b></span><span>통계적 신뢰구간 아님</span></div>${fixtureNote()}</figure><div class="score-strip"><div class="score-icon">${icon('target')}</div><div><strong>${error<=5?'예시 결과에 가까운 예측이에요':error<=15?'꽤 가까이 맞혔어요!':'이런 생각의 차이가 있었네요!'}</strong><p>내 예측 ${r.prediction}% · 예시와 <b>${error}%p 차이</b></p></div><div class="score-number">${score}<small>점</small><span>체험 점수</span></div></div></section><section class="panel" id="visitor-section">${visitor(q)}</section><details class="panel detail-panel"><summary>세대·성별로는 얼마나 다를까? ${icon('chevron')}</summary><div class="section-heading compact"><h2>집단별 선택</h2><div class="segmented" aria-label="비교 집단"><button data-action="group" data-value="age" aria-pressed="${state.group==='age'}" class="${state.group==='age'?'active':''}">연령별</button><button data-action="group" data-value="gender" aria-pressed="${state.group==='gender'}" class="${state.group==='gender'?'active':''}">성별</button></div></div><div id="group-chart">${groups(q)}</div><p class="micro">집단의 평균은 개인을 설명하지 않아요. 집단별 불확실성 미산출.</p></details><details class="panel detail-panel"><summary>왜 그렇게 골랐을까? ${icon('chevron')}</summary><div class="reason-grid"><article><span class="reason-label">${q.a} 쪽의 생각</span><p>“${q.reasonA}”</p></article><article><span class="reason-label alternate">${q.b} 쪽의 생각</span><p>“${q.reasonB}”</p></article></div><p class="micro">실제 응답이나 합성 시민 발언이 아닌, 화면 시연을 위해 작성한 의견 예시입니다.</p></details><section class="panel evidence-panel"><details><summary>데이터와 신뢰도 확인하기 ${icon('chevron')}</summary><div class="evidence-content">${evidenceContent()}</div></details></section></div><div class="result-actions"><a class="primary" href="#/predict/${next.id}">다음 민심 맞히기 ${icon('arrow')}</a><button class="secondary" data-action="share" data-id="${q.id}">${icon('share')} 결과 카드</button><button class="secondary" data-action="save" data-id="${q.id}" aria-pressed="${state.saved.has(q.id)}">${icon('bookmark')} 저장</button></div></div>`,'play','민심 결과')}
function evidenceContent(){return `<p><strong>현재 상태: 엔진 연결 전 · 신뢰도 미평가</strong></p><p>이 화면의 비율, 범위, 집단 차이, 참여 수는 UI 체험용으로 준비한 예시입니다. 실제 공개 조사 데이터를 분석하거나 시뮬레이션한 결과가 아닙니다.</p><dl class="evidence-list"><div><dt>관련 조사·문항</dt><dd>미연결</dd></div><div><dt>모델·스냅샷·기준 시점</dt><dd>미연결</dd></div><div><dt>합성 인구 규모·가중치</dt><dd>미산출</dd></div><div><dt>검증 오차·예측 불확실성</dt><dd>미평가</dd></div></dl><p>엔진 연결 후에는 직접 관련된 실제 조사와 검증 결과에 따라 ‘높음 / 보통 / 실험적’으로 구분하고, 근거가 부족한 경우 추정 범위를 함께 표시할 예정입니다.</p>`}
function records(){const items=questions.filter(q=>state.records[q.id]),avg=items.length?(items.reduce((s,q)=>s+Math.abs(q.value-state.records[q.id].prediction),0)/items.length).toFixed(1):'—';shell(`<div class="page-heading"><div><div class="eyebrow">GET TO KNOW YOUR INSTINCT</div><h1>나의 기록</h1><p>지금까지의 예측과 내가 만든 질문.</p></div></div><div class="record-stats"><div><span>참여한 질문</span><strong>${items.length}<small>개</small></strong></div><div><span>평균 예측 차이</span><strong>${avg}<small>%p</small></strong></div><div><span>저장한 질문</span><strong>${state.saved.size}<small>개</small></strong></div></div><div class="notice">화면 시연용 예시와 비교한 개인 체험 기록입니다. 실제 민심 예측 능력이나 전체 사용자 순위가 아닙니다.${storageAvailable?' 이 브라우저에만 저장돼요.':' 현재 브라우저에서 저장을 사용할 수 없어요.'}</div><div class="section-heading"><h2>나의 예측 기록</h2><span class="micro">처음 제출한 예측을 기록해요</span></div>${items.length?`<div class="history-list">${items.map(q=>`<a href="#/result/${q.id}" class="history-item"><div><span class="category">${q.category}</span><h3>${q.title}</h3><p>내 예측 ${state.records[q.id].prediction}% · 예시 결과 ${q.value}%</p></div><strong>${scoreFor(q,state.records[q.id])}<small>점 · 체험</small></strong>${icon('chevron')}</a>`).join('')}</div>`:'<div class="empty">'+icon('target')+'<h2>첫 번째 민심 감각을 발견해 볼까요?</h2><p>질문 하나로 가볍게 시작해 보세요.</p><a href="#/predict/workweek" class="primary">오늘의 민심 예측하기</a></div>'}<div class="section-heading"><h2>내가 만든 질문 초안</h2><button class="text-button" data-action="create">새 질문 만들기 ＋</button></div>${state.drafts.length?`<div class="history-list">${state.drafts.map((d,i)=>`<button class="history-item draft-item" data-action="edit-draft" data-index="${i}"><div><span class="category">비공개 초안 · 시뮬레이션 대기</span><h3>${esc(d.title)}</h3><p>${esc(d.a)} / ${esc(d.b)} · ${esc(d.condition||'추가 조건 없음')}</p></div>${icon('chevron')}</button>`).join('')}</div>`:'<div class="empty small-empty"><p>대한민국에 물어보고 싶은 질문을 초안으로 남겨두세요.</p><button class="secondary" data-action="create">질문 초안 만들기</button></div>'}`,'records','나의 기록')}
let draftState=null,modalTrigger=null;
function openModal(title,body){const m=document.querySelector('#modal');if(!m.open)modalTrigger=document.activeElement;m.innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close" aria-label="닫기">${icon('close')}</button></div>${body}`;if(!m.open)m.showModal();else m.querySelector('input,textarea,button')?.focus()}
function createQuestion(text='',index=null){draftState=index!==null?{...state.drafts[index],index}:{title:text,type:'agree',a:'찬성',b:'반대',condition:'',population:'대한민국 만 18세 이상',index:null};openModal('대한민국에 물어보세요',`<div class="modal-steps"><b>1 질문 쓰기</b><span>2 질문 다듬기</span></div><p class="modal-copy">대한민국의 선택이 궁금한 질문을 적어보세요.</p><form id="draft-step-one"><label class="field-label" for="draft-title">궁금한 질문</label><textarea id="draft-title" name="title" rows="3" required minlength="8" maxlength="180" placeholder="예: 월급이 그대로라면 주 4일제에 찬성할까?">${esc(draftState.title)}</textarea><div class="field-help">8–180자 · 한 번에 하나의 주제를 물어보세요.</div><label class="field-label" for="question-type">질문 유형</label><select id="question-type" name="type" class="form-select"><option value="agree" ${draftState.type==='agree'?'selected':''}>찬반형 · 찬성 / 반대</option><option value="choice" ${draftState.type==='choice'?'selected':''}>양자선택형 · 두 선택지 비교</option></select><div class="notice" style="margin-top:20px">질문을 서버로 전송하지 않습니다. 다음 단계에서 대상·조건·선택지를 직접 다듬어 비공개 초안으로 저장할 수 있어요.</div><button type="submit" class="primary full" style="margin-top:20px">질문 다듬기 ${icon('arrow')}</button></form>`)}
function refineQuestion(){const d=draftState;openModal('질문 다듬기',`<div class="modal-steps"><span>1 질문 쓰기</span><b>2 질문 다듬기</b></div><p class="modal-copy">AI 정규화 연결 전입니다. 질문의 전제를 직접 확인해 주세요.</p><form id="draft-step-two"><label class="field-label" for="refined-title">질문</label><textarea id="refined-title" name="title" rows="2" required minlength="8" maxlength="180">${esc(d.title)}</textarea><label class="field-label" for="population">대상</label><input id="population" name="population" class="form-input" value="${esc(d.population)}" required maxlength="80"><label class="field-label" for="condition">전제 조건 <span>선택</span></label><input id="condition" name="condition" class="form-input" value="${esc(d.condition)}" maxlength="180" placeholder="예: 기존 월급 유지, 주당 근무일만 축소"><div class="field-grid"><div><label class="field-label" for="choice-a">선택지 A</label><input id="choice-a" name="a" class="form-input" value="${esc(d.a)}" required maxlength="30" placeholder="첫 번째 선택"></div><div><label class="field-label" for="choice-b">선택지 B</label><input id="choice-b" name="b" class="form-input" value="${esc(d.b)}" required maxlength="30" placeholder="두 번째 선택"></div></div><p class="form-error" id="draft-error" role="alert"></p><div class="notice" style="margin-top:20px">초안은 이 브라우저에만 저장됩니다. 엔진 연결과 근거 검토 전까지 결과 생성 및 피드 공개는 진행되지 않아요.</div><button type="submit" class="primary full" style="margin-top:20px">비공개 초안 저장 ${icon('check')}</button></form>`)}
function shareCard(q){const r=state.records[q.id];openModal('내 결과 카드',`<p class="modal-copy">예시 데이터라는 안내가 카드에 함께 표시됩니다.</p><canvas id="share-canvas" width="1080" height="1080" aria-label="${esc(q.title)} 내 예측 ${r.prediction}퍼센트, 예시 결과 ${q.value}퍼센트. 화면 시연용 예시, 실제 시뮬레이션 미실행."></canvas><div class="modal-actions"><button class="primary" data-action="download" data-id="${q.id}">${icon('download')} 이미지 저장</button><button class="secondary" data-action="copy-link" data-id="${q.id}">${icon('share')} 질문 링크 복사</button></div><p class="micro" style="margin-top:12px">링크는 질문의 예측 화면을 열어요. 내 예측 기록은 전송되지 않아요.</p>`);drawShare(q)}
function drawShare(q){const canvas=document.querySelector('#share-canvas'),c=canvas.getContext('2d'),r=state.records[q.id];c.fillStyle='#f8faf9';c.fillRect(0,0,1080,1080);c.fillStyle='#13854b';c.font='bold 38px Pretendard, sans-serif';c.fillText('민심테스트',76,104);c.font='24px Pretendard, sans-serif';c.fillText('당신의 질문에 대한민국은 어떻게 답할까?',76,153);c.fillStyle='#171d1a';c.font='bold 55px Pretendard, sans-serif';let line='',y=280;for(const ch of q.title){if(c.measureText(line+ch).width>905){c.fillText(line,76,y);line=ch;y+=78}else line+=ch}c.fillText(line,76,y);c.font='24px Pretendard, sans-serif';c.fillStyle='#616963';const condition=`${q.condition}`;let conditionLine='';let cy=465;for(const ch of condition){if(c.measureText(conditionLine+ch).width>900){c.fillText(conditionLine,76,cy);conditionLine=ch;cy+=34}else conditionLine+=ch}c.fillText(conditionLine,76,cy);c.fillStyle='#ffffff';c.fillRect(76,535,928,237);c.fillStyle='#59645e';c.font='26px Pretendard, sans-serif';c.fillText('나의 예측',115,590);c.fillText('예시 결과',580,590);c.fillStyle='#166c42';c.font='bold 86px Pretendard, sans-serif';c.fillText(`${r.prediction}%`,112,707);c.fillText(`${q.value}%`,577,707);c.font='25px Pretendard, sans-serif';c.fillStyle='#59645e';c.fillText(`‘${q.a}’ 선택 비율 · 범위 예시 ${q.range[0]}–${q.range[1]}%`,76,824);c.font='bold 28px Pretendard, sans-serif';c.fillStyle='#263b2e';c.fillText('화면 시연용 예시 · 실제 시뮬레이션 미실행',76,932);c.font='23px Pretendard, sans-serif';c.fillText('실제 여론조사 아님 · 신뢰도 미평가 · 통계적 신뢰구간 아님',76,979)}
function render(){const path=location.hash.slice(1)||'/';const [_,page,id]=path.split('/');if(!page)home();else if(page==='feed')explore();else if(page==='saved')explore(true);else if(page==='records')records();else if(page==='predict'||page==='result'){const q=questions.find(q=>q.id===id);if(q){page==='result'?result(q):prediction(q)}else shell('<div class="empty"><h1>질문을 찾을 수 없어요</h1><p>링크를 확인하거나 다른 질문을 둘러보세요.</p><a class="primary" href="#/feed">질문 둘러보기</a></div>')}else shell('<div class="empty"><h1>아직 없는 페이지예요</h1><a class="primary" href="#/">홈으로 가기</a></div>');document.title=(page==='predict'||page==='result'?questions.find(q=>q.id===id)?.title+' | ':'')+'민심테스트';}
document.addEventListener('click',async e=>{if(e.target.closest('.skip-link')){e.preventDefault();document.querySelector('#main').focus();return}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,q=questions.find(q=>q.id===el.dataset.id);if(a==='research-condition'&&q?.research&&q.conditions[el.dataset.value]){state.researchConditions[q.id]=el.dataset.value;result(q);document.querySelector(`[data-action="research-condition"][data-value="${el.dataset.value}"]`)?.focus({preventScroll:true});return}if(a==='research-vote'&&q?.research&&q.options[el.dataset.value]&&q.conditions[el.dataset.condition]){state.votes[q.id+':'+el.dataset.condition]=el.dataset.value;persist();result(q);document.querySelector(`[data-action="research-vote"][data-value="${el.dataset.value}"]`)?.focus({preventScroll:true});return}if(a==='save'){state.saved.has(el.dataset.id)?state.saved.delete(el.dataset.id):state.saved.add(el.dataset.id);persist();el.classList.toggle('saved',state.saved.has(el.dataset.id));el.setAttribute('aria-pressed',state.saved.has(el.dataset.id));if(q?.research)el.textContent=el.classList.contains('bookmark')?(state.saved.has(q.id)?'★':'☆'):(state.saved.has(q.id)?'★ 저장됨':'☆ 저장');toast(storageAvailable?(state.saved.has(el.dataset.id)?'질문을 저장했어요.':'저장을 해제했어요.'):'저장 공간을 사용할 수 없어 현재 화면에서만 유지돼요.');if(location.hash==='#/saved')explore(true)}if(a==='filter'){state.filter=el.dataset.value;document.querySelectorAll('[data-action="filter"]').forEach(b=>{b.classList.toggle('active',b.dataset.value===state.filter);b.setAttribute('aria-pressed',b.dataset.value===state.filter)});document.querySelector('#feed-grid').innerHTML=feedCards()}if(a==='suggest')location.hash=`/predict/${el.dataset.id}`;if(a==='create')createQuestion();if(a==='edit-draft')createQuestion('',Number(el.dataset.index));if(a==='close')document.querySelector('#modal').close();if(a==='about')openModal('질문으로 만나는, 다양한 대한민국',`<p class="modal-copy">민심테스트는 공개 조사 데이터를 기반으로 구성한 합성 인구의 예상 반응을 탐색하고, 게임처럼 예측·비교하는 서비스입니다.</p><div class="about-steps"><div><b>01</b><span><strong>궁금한 질문을 고르고</strong><p>일, 관계, 기술부터 평소의 작은 궁금증까지.</p></span></div><div><b>02</b><span><strong>모두의 생각을 예측하고</strong><p>내 의견과 다른 사람의 생각을 구분해 보세요.</p></span></div><div><b>03</b><span><strong>그 차이와 이유를 발견해요</strong><p>전체 비율뿐 아니라 집단의 차이와 한계도 함께.</p></span></div></div><div class="notice">실행된 시뮬레이션 2문항과 화면 체험용 예시 질문을 구분해 제공합니다. 자유 질문의 실시간 처리, AI 질문 정규화, 방문자 통계 집계는 아직 연결되지 않았습니다.</div><button class="primary full" data-action="close" style="margin-top:20px">알겠어요</button>`);if(a==='evidence')openModal('숫자와 근거를 함께 봐요',`<div class="evidence-content">${evidenceContent()}</div>`);if(a==='group'){state.group=el.dataset.value;const id=location.hash.split('/').pop();document.querySelector('#group-chart').innerHTML=groups(questions.find(q=>q.id===id));document.querySelectorAll('[data-action="group"]').forEach(b=>{b.classList.toggle('active',b.dataset.value===state.group);b.setAttribute('aria-pressed',b.dataset.value===state.group)})}if(a==='vote'&&q){state.votes[q.id]=el.dataset.value;persist();document.querySelector('#visitor-section').innerHTML=visitor(q);document.querySelector(`[data-action="vote"][data-value="${el.dataset.value}"]`).focus();toast(storageAvailable?'내 생각이 이 브라우저에 기록됐어요.':'저장 공간을 사용할 수 없어 투표는 현재 화면에서만 유지돼요.')}if(a==='share'&&q)shareCard(q);if(a==='download'&&q){const canvas=document.querySelector('#share-canvas');canvas.toBlob(blob=>{if(!blob){toast('이미지를 만들지 못했어요. 다시 시도해 주세요.');return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`민심테스트-${q.id}-체험결과.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('결과 카드 이미지를 저장했어요.')},'image/png')}if(a==='copy-link'&&q){const url=new URL(location.href);url.hash=`/${q.research?'result':'predict'}/${q.id}`;try{await navigator.clipboard.writeText(url.href);toast('질문 링크를 복사했어요.')}catch{const p=document.createElement('p');p.className='copy-fallback';p.textContent='아래 링크를 직접 복사해 주세요.';const input=document.createElement('input');input.className='form-input';input.readOnly=true;input.value=url.href;p.append(input);if(!document.querySelector('#modal').open)openModal('질문 링크','');document.querySelector('#modal').append(p);input.select()}}});
document.addEventListener('submit',e=>{const f=e.target;if(f.id==='quick-question'){e.preventDefault();const title=new FormData(f).get('question').trim();if(title.length<8||title.length>180){document.querySelector('#quick-question-input').setCustomValidity('궁금한 질문을 8–180자로 입력해 주세요.');f.reportValidity();return}createQuestion(title)}if(f.id==='search-form'){e.preventDefault();state.search=new FormData(f).get('search').trim();state.filter='전체';if(location.hash==='#/feed')explore();else location.hash='/feed'}if(f.id==='prediction-form'){e.preventDefault();const q=questions.find(q=>q.id===f.dataset.id),prediction=Number(new FormData(f).get('prediction'));if(!Number.isInteger(prediction)||prediction<0||prediction>100)return;if(!state.records[q.id]){state.records[q.id]={prediction,at:new Date().toISOString()};persist()}if(location.hash===`#/result/${q.id}`)render();else location.hash=`/result/${q.id}`}if(f.id==='draft-step-one'){e.preventDefault();const d=new FormData(f),title=d.get('title').trim();if(title.length<8){document.querySelector('#draft-title').setCustomValidity('8자 이상으로 질문을 입력해 주세요.');f.reportValidity();return}const type=d.get('type');draftState={...draftState,title,type,a:type==='choice'&&draftState.type!=='choice'?'':draftState.a,b:type==='choice'&&draftState.type!=='choice'?'':draftState.b};refineQuestion()}if(f.id==='draft-step-two'){e.preventDefault();const d=Object.fromEntries(new FormData(f));for(const k of Object.keys(d))d[k]=d[k].trim();if(d.title.length<8||!d.a||!d.b||!d.population){document.querySelector('#draft-error').textContent='질문은 8자 이상, 대상과 선택지는 공백 없이 입력해 주세요.';return}if(d.a===d.b){document.querySelector('#draft-error').textContent='서로 다른 두 선택지를 입력해 주세요.';return}const {index,...original}=draftState;const draft={...original,...d};if(index!==null)state.drafts[index]=draft;else state.drafts.unshift(draft);persist();document.querySelector('#modal').close();location.hash='/records';if(location.hash==='#/records')records();toast(storageAvailable?'질문 초안을 저장했어요. 엔진 연결 후 결과를 생성할 수 있어요.':'저장 공간을 사용할 수 없어 초안은 현재 화면에서만 유지돼요.')}});
document.addEventListener('input',e=>{if(['draft-title','quick-question-input'].includes(e.target.id))e.target.setCustomValidity('');if(['prediction-range','prediction-number'].includes(e.target.id)){const v=e.target.value;if(v===''||!Number.isFinite(Number(v))||Number(v)<0||Number(v)>100)return;document.querySelector('#prediction-number').value=v;const range=document.querySelector('#prediction-range');range.value=v;range.style.setProperty('--fill',`${v}%`);range.setAttribute('aria-valuetext',`${v}퍼센트`);document.querySelector('#option-a').textContent=`${v}%`;document.querySelector('#option-b').textContent=`${100-Number(v)}%`}});
document.addEventListener('keydown',e=>{if(e.target.id==='quick-question-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&e.keyCode!==229){e.preventDefault();e.target.form.requestSubmit()}});
document.querySelector('#modal').addEventListener('close',()=>modalTrigger?.isConnected&&modalTrigger.focus());
document.addEventListener('change',e=>{if(e.target.matches('.sort')){state.sort=e.target.value;document.querySelector('#feed-grid').innerHTML=feedCards()}});
window.addEventListener('hashchange',()=>{document.querySelector('#modal').close();render();window.scrollTo(0,0);document.querySelector('#main').focus({preventScroll:true})});render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'list_demo_questions',description:'List available questions and choices; distinguishes executed simulations from demo fixtures.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>questions.map(q=>({id:q.id,title:q.title,category:q.category,choices:q.research?Object.values(q.options):[q.a,q.b],demo:!q.research}))});register({name:'open_prediction_question',description:'Open a question. Executed simulations open their result; demo fixtures open prediction or the previously saved result.',inputSchema:{type:'object',properties:{questionId:{type:'string'}},required:['questionId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.questionId!=='string'||!questions.some(q=>q.id===input.questionId))throw new Error('Unknown questionId');history.replaceState(null,'',`#/predict/${input.questionId}`);render();return {questionId:input.questionId,view:questions.find(q=>q.id===input.questionId).research||state.records[input.questionId]?'result':'prediction',demo:!questions.find(q=>q.id===input.questionId).research}}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
